svg.script:
(function () {
  var root = document.getElementById('a16p14-svg');
  if (!root) return;

  var tooltip = document.getElementById('a16p14-tooltip');
  var tipTitle = document.getElementById('a16p14-tip-title');
  var tipBody = document.getElementById('a16p14-tip-body');
  var tipBg = document.getElementById('a16p14-tip-bg');
  var calloutKicker = document.getElementById('a16p14-callout-kicker');
  var calloutTitle = document.getElementById('a16p14-callout-title');
  var calloutBody = document.getElementById('a16p14-callout-body');

  var modes = {
    janelas: {
      kicker: 'LEITURA DE PROVA',
      title: 'Três janelas no eixo · risco sobe da amnio para a cordo',
      body: 'BVC 10–13 · amnio em geral após 16 (≥14 com risco maior) · cordo após 18. Toque uma faixa para focar.'
    },
    riscos: {
      kicker: 'HIERARQUIA',
      title: 'Amnio ~0,5% · cordo 1–3% · BVC mais risco que amnio',
      body: 'Números de banca. Séries modernas de amnio frequentemente menores — nuance, sem inventar taxa de BVC.'
    },
    amnio: {
      kicker: 'POR QUE AMNIO',
      title: 'Na aneuploidia predomina amnio · cordo não é rotina',
      body: 'Menor risco entre os três. LA em bolsão guiado por US. Cordo é ponte de doença hemolítica, não 1ª linha de cariótipo.'
    }
  };

  function setMode(mode) {
    if (!modes[mode]) mode = 'janelas';
    root.setAttribute('data-mode', mode);
    var m = modes[mode];
    if (calloutKicker) calloutKicker.textContent = m.kicker;
    if (calloutTitle) calloutTitle.textContent = m.title;
    if (calloutBody) calloutBody.textContent = m.body;
    var btns = root.querySelectorAll('[data-mode-btn]');
    for (var i = 0; i < btns.length; i++) {
      var b = btns[i];
      if (b.getAttribute('data-mode-btn') === mode) b.classList.add('a16p14-active');
      else b.classList.remove('a16p14-active');
    }
    if (mode === 'amnio') {
      root.setAttribute('data-focus', 'amnio');
    } else if (root.getAttribute('data-focus') === 'amnio' && mode !== 'amnio') {
      root.setAttribute('data-focus', 'none');
    }
  }

  function setFocus(focus) {
    var cur = root.getAttribute('data-focus');
    if (focus && focus === cur) focus = 'none';
    root.setAttribute('data-focus', focus || 'none');
    if (focus === 'bvc') {
      if (calloutKicker) calloutKicker.textContent = 'B · VILÓSIDADE';
      if (calloutTitle) calloutTitle.textContent = '10–13 sem · diagnóstico precoce · risco > amnio';
      if (calloutBody) calloutBody.textContent = 'Biópsia de vilo corial. Fecha cariótipo cedo, mas não é o de menor risco. Hierarquia: mais risco que amnio.';
    } else if (focus === 'amnio') {
      if (calloutKicker) calloutKicker.textContent = 'A · LÍQUIDO';
      if (calloutTitle) calloutTitle.textContent = 'Após 16 sem (geral) · ~0,5% · menor risco';
      if (calloutBody) calloutBody.textContent = 'A partir de 14 com risco maior. Coleta de LA em bolsão guiada por US. Predomina em aneuploidia/malformação.';
    } else if (focus === 'cordo') {
      if (calloutKicker) calloutKicker.textContent = 'C · CORDÃO';
      if (calloutTitle) calloutTitle.textContent = 'Após 18 sem · óbito 1–3% · ponte hemolítica';
      if (calloutBody) calloutBody.textContent = 'Punciona o cordão. Não é invasivo de rotina para aneuploidia. Central em doença hemolítica (hematimetria/transfusão).';
    } else {
      var mode = root.getAttribute('data-mode') || 'janelas';
      setMode(mode);
      return;
    }
  }

  var modeBtns = root.querySelectorAll('[data-mode-btn]');
  for (var mi = 0; mi < modeBtns.length; mi++) {
    (function (el) {
      function go() { setMode(el.getAttribute('data-mode-btn')); }
      el.addEventListener('click', go);
      el.addEventListener('keydown', function (e) {
        if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); go(); }
      });
    })(modeBtns[mi]);
  }

  var focusBtns = root.querySelectorAll('[data-focus-btn]');
  for (var fi = 0; fi < focusBtns.length; fi++) {
    (function (el) {
      function go() { setFocus(el.getAttribute('data-focus-btn')); }
      el.addEventListener('click', go);
      el.addEventListener('keydown', function (e) {
        if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); go(); }
      });
    })(focusBtns[fi]);
  }

  function wrapBody(text, maxChars) {
    var words = (text || '').split(/\s+/);
    var lines = [];
    var cur = '';
    for (var i = 0; i < words.length; i++) {
      var trial = cur ? cur + ' ' + words[i] : words[i];
      if (trial.length > maxChars && cur) {
        lines.push(cur);
        cur = words[i];
      } else {
        cur = trial;
      }
    }
    if (cur) lines.push(cur);
    return lines.slice(0, 4);
  }

  function showTip(title, body, clientX, clientY) {
    if (!tooltip || !tipTitle || !tipBody) return;
    tipTitle.textContent = title || '';
    while (tipBody.firstChild) tipBody.removeChild(tipBody.firstChild);
    var lines = wrapBody(body, 40);
    for (var i = 0; i < lines.length; i++) {
      var t = document.createElementNS('http://www.w3.org/2000/svg', 'tspan');
      t.setAttribute('x', '12');
      t.setAttribute('dy', i === 0 ? '0' : '14');
      t.textContent = lines[i];
      tipBody.appendChild(t);
    }
    var th = 36 + Math.max(1, lines.length) * 14;
    if (tipBg) {
      tipBg.setAttribute('width', '280');
      tipBg.setAttribute('height', String(th));
    }
    tooltip.classList.add('a16p14-show');
    moveTip(clientX, clientY);
  }

  function moveTip(clientX, clientY) {
    if (!tooltip || !tooltip.classList.contains('a16p14-show')) return;
    var ctm = root.getScreenCTM();
    if (!ctm) return;
    var pt = root.createSVGPoint();
    pt.x = clientX;
    pt.y = clientY;
    var sp = pt.matrixTransform(ctm.inverse());
    var x = sp.x + 14;
    var y = sp.y + 14;
    var vb = root.viewBox.baseVal;
    var maxX = (vb && vb.width ? vb.width : 1000) - 292;
    var maxY = (vb && vb.height ? vb.height : 860) - 90;
    if (x > maxX) x = sp.x - 294;
    if (y > maxY) y = sp.y - 90;
    if (x < 8) x = 8;
    if (y < 8) y = 8;
    tooltip.setAttribute('transform', 'translate(' + x + ',' + y + ')');
  }

  function hideTip() {
    if (tooltip) tooltip.classList.remove('a16p14-show');
  }

  var tips = root.querySelectorAll('[data-tip-title]');
  for (var t = 0; t < tips.length; t++) {
    (function (el) {
      el.addEventListener('mouseenter', function (e) {
        showTip(el.getAttribute('data-tip-title'), el.getAttribute('data-tip-body'), e.clientX, e.clientY);
      });
      el.addEventListener('mousemove', function (e) { moveTip(e.clientX, e.clientY); });
      el.addEventListener('mouseleave', hideTip);
      el.addEventListener('focus', function () {
        var r = el.getBoundingClientRect();
        showTip(el.getAttribute('data-tip-title'), el.getAttribute('data-tip-body'), r.left + r.width / 2, r.top);
      });
      el.addEventListener('blur', hideTip);
    })(tips[t]);
  }

  root.addEventListener('mousemove', function (e) { moveTip(e.clientX, e.clientY); });

  setMode('janelas');
})();
